/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ApplyValue, ApplyItem, ApplyChoice, ApplyIdentityLine, ReviewApplySelection, ApplyPositionBlock,
 *          ProposedValues, ReviewApplyModel
 *   Functions: memberKey, reviewApplyModel
 * Internal
 *   Types: CreditView, Applied, Numbers
 *   Functions: pathOf, sameCredits, artistEntries, firstLabel, positionOf, numeric
 * @end-catalog */

import { reviewChanges, reviewFieldKey, type CatalogReview, type ReviewChange, type ReviewDraft, type ReviewField } from './catalogReviewApi';
import type { ReviewIdentityResponse, ReviewLookupResponse } from './catalogReviewLookupApi';
import { expectedRowMembers, pairingFilledNumbers } from './catalogReviewSummaryModel';
import type { ReviewLookupView } from './importLookupApi';

/**
 * What the Update original Album step of an existing-Album review shows and sends (owner rules: docs/business-rules.md, Catalog
 * Visibility and Administration, applying an existing-Album review): every change an apply can write, from the saved draft, the
 * lookup summary and the identity read, with its default selection, the holds the server's checks impose (an unanswered lookup
 * conflict, a pairing-filled number without the tracklist that places it, a tracklist whose paired members are off their rows),
 * the identities the selected lists and label own, and the apply body. Mirrors applyReview's checks so a ready selection is one
 * the server admits, and adds the review page's own: no two members left at one Disc and Track position, and no number outside the
 * server's bounds. Pure.
 */

type CreditView = ReviewIdentityResponse['members'][number]['current'][number];
type Applied = NonNullable<ReviewLookupView['applied']>;
type Numbers = { slotId: string; discNumber: number | null; trackNumber: number | null };
/** An item's values: a title, date or number, a list of Credits (the Album's Artist entries or label), the tracklist, or a member's Credits. */
export type ApplyValue =
  | { kind: 'value'; baseline: unknown; value: unknown }
  | { kind: 'credits'; current: CreditView[]; next: CreditView[]; idsOnly: boolean }
  | { kind: 'tracklist'; keptRows: number | null; keptNoFile: number; rows: number; noFile: number }
  | { kind: 'member'; current: CreditView[]; next: CreditView[]; removed: CreditView[]; attribution: { from: 'documented' | 'unknown' | null; to: 'documented' } | null; idsOnly: boolean };
/**
 * One change the step lists. `hold` says why it cannot be selected now: its lookup conflict is unanswered, a pairing-filled number
 * waits for the tracklist, the tracklist's paired members (`offSlotIds`) are off their rows, or a cleaned title waits for its
 * member's numbers. `basis` is the values the change rests on (the review's draft and source, never what identity decisions
 * resolve), the same before and after the draft is saved: an explicit choice holds while it is the same.
 */
export type ApplyItem = { key: string; scope: 'album' | 'track'; slotId: string | null; field: ReviewField['field'] | 'artists'; title: string; member: boolean;
  value: ApplyValue; selected: boolean; hold: null | 'conflict' | 'tracklist' | 'placement' | 'numbers'; offSlotIds: string[]; basis: string };
/** An administrator's explicit choice of an item, made on the item's `basis`. */
export type ApplyChoice = { checked: boolean; basis: string };
/** An Artist or label identity a selected list or the selected label owns: what applying does with it and the MusicBrainz ID it records. */
export type ApplyIdentityLine = { handle: string; scope: 'artist' | 'label'; name: string; musicBrainzId: string | null; outcome: 'reuse' | 'create' | 'conflicting' | 'undecided';
  records: { name: string; hidden: boolean }[]; idWrite: { musicBrainzId: string; replaces: string | null; record: string | null } | null; needsAnswer: boolean };
/** A frozen selection: the apply body's parts, and what its confirmation shows (the selected items, identities and the Album note's slots). */
export type ReviewApplySelection = { fields: ReviewField[]; memberCredits: string[]; preselections: ReviewIdentityResponse['preselections'];
  musicBrainzIds: ReviewIdentityResponse['musicBrainzIds']; items: ApplyItem[]; identities: ApplyIdentityLine[]; albumNote: { namingReplaced: string[] } | null };
/**
 * Members whose numbers stop the update: several left at one position (a missing Disc Number counting as 1) where a selected
 * number moves one of them there, or a selected number outside the server's bounds (Disc 1-999, Track 1-9999).
 */
export type ApplyPositionBlock = { reason: 'duplicate' | 'range'; slotIds: string[] };
/**
 * What the captured titles give the defaults (catalogReviewProposal.ts titleDefaults), by item key: the Disc and Track Numbers of
 * an accepted Disc and Track proposal, which start selected where they fill an empty stored value, and each member's cleaned
 * title with the numbers it applies only with.
 */
export type ProposedValues = { numbers: ReadonlyMap<string, number>; titles: ReadonlyMap<string, { title: string; numbers: readonly ('discNumber' | 'trackNumber')[] }> };
export type ReviewApplyModel = { items: ApplyItem[]; selection: ReviewApplySelection; blocking: { lookup: boolean; identities: string[]; positions: ApplyPositionBlock[] }; ready: boolean };

/** The choice key of a member's Credits. */
export const memberKey = (slotId: string) => `member:${slotId}`;
const pathOf = (item: Pick<ApplyItem, 'scope' | 'slotId' | 'field'>) => item.scope === 'album' ? `album.${item.field}` : `tracks.${item.slotId}.${item.field}`;
const sameCredits = (left: CreditView[], right: CreditView[]) => JSON.stringify(left.map(({ subjectId, identity, name, role, joinPhrase }) => [subjectId, identity, name, role, joinPhrase]))
  === JSON.stringify(right.map(({ subjectId, identity, name, role, joinPhrase }) => [subjectId, identity, name, role, joinPhrase]));
const artistEntries = (credits: CreditView[]) => credits.filter(credit => credit.subjectType === 'artist' && (credit.role === 'primary' || credit.role === 'featured'));
const firstLabel = (credits: CreditView[]) => credits.filter(credit => credit.subjectType === 'organization' && credit.role === 'label').slice(0, 1);
/** A member's position as the Album page places it: no Track Number is no position, a missing Disc Number is disc 1. */
const positionOf = (numbers: Numbers | undefined) => numbers && numbers.trackNumber !== null ? `${numbers.discNumber ?? 1}:${numbers.trackNumber}` : null;
/** Whether an item's field is a member's Disc or Track Number. */
const numeric = (field: string): field is 'discNumber' | 'trackNumber' => field === 'discNumber' || field === 'trackNumber';

/**
 * The step's items in order (the Album's title and date, Artist entries, label and expected tracklist, each Track's title, Disc and
 * Track Number, then each member's Credits), each selected by its explicit choice while that choice's basis is the item's, else by
 * default. A value that replaces a stored one starts unselected, except a cleaned title and a conflict answered with the lookup
 * value, which the administrator asked for; of the rest, values lookup filled, a saved Disc or Track Number at its member's pair
 * position (the applied pairing rests on it), numbers an accepted Disc and Track title proposal gives (`proposed`) and the
 * tracklist start selected, as do the Album's Artist entries, label and each member's Credits unless an identity row they own still
 * needs an answer; other manual and Luna-adopted values do not. A cleaned title is held until its member's numbers are selected or
 * stored. A format-2 or applied review, or a read still missing, lists field items only. `draft`, when given, is the editor's draft,
 * which the items and count describe with the same bases as once saved; it is never ready, as only the saved draft applies (the
 * caller reads readiness without it). Ready when something is selected, nothing waits (lookup, analysis, an identity a selected
 * list or the label needs answered), no member's numbers block (`blocking.positions`) and a captured review's summary and identity
 * reads are both of the review's revision and value revision.
 */
export function reviewApplyModel({ item: saved, draft: edited, lookup, summary, waiting, identity, choices, proposed }: { item: CatalogReview; draft?: ReviewDraft;
  lookup: ReviewLookupView | null; summary: Pick<ReviewLookupResponse, 'revision' | 'valueRevision'> | null; waiting: { lookup: boolean; analysis: boolean } | null;
  identity: ReviewIdentityResponse | null; choices: Readonly<Record<string, ApplyChoice>>; proposed?: ProposedValues }): ReviewApplyModel {
  const item = edited ? { ...saved, draft: edited } : saved;
  const { draft, source } = item, captured = draft.album.expectedTracklist !== undefined, reads = captured && identity !== null;
  const applied: Applied | null = lookup?.applied && lookup.applied.choice !== 'none' ? lookup.applied : null, pairs = applied?.pairs ?? null;
  const open = new Set(lookup?.needsAnswer.conflicts ?? []), filled = pairingFilledNumbers(lookup, draft);
  const fromLookup = (path: string) => Boolean(applied?.values.some(value => value.path === path));
  // A conflict the administrator answered with the lookup value is their explicit choice, as a cleaned title is, while the draft keeps that value.
  const answeredLookup = ({ scope, slotId, field: name, value }: ReviewChange) => Boolean(applied?.conflicts.some(conflict => conflict.answer === 'lookup'
    && conflict.path === pathOf({ scope, slotId, field: name }) && JSON.stringify(conflict.lookup) === JSON.stringify(value)));
  // A saved Disc or Track Number at its member's pair position is one the applied pairing rests on (a number fixed so lookup re-ranked).
  const atPair = ({ field, slotId, value }: ReviewChange) => numeric(field) && Boolean(pairs?.some(pair => pair.slotId === slotId && pair[field] === value));
  const items: (ApplyItem & { default: boolean })[] = [];
  const add = (value: Omit<ApplyItem, 'selected' | 'hold' | 'offSlotIds'> & { default: boolean }) => items.push({ ...value, selected: false, hold: null, offSlotIds: [] });
  // A cleaned title and a conflict answered with the lookup value are selected as asked; nothing else that replaces a stored value
  // (any but none or an empty title; numbers start at 1) is.
  const changes = reviewChanges(item), field = (change: ReviewChange, key = reviewFieldKey(change)) => add({ key, scope: change.scope, slotId: change.slotId, field: change.field,
    title: change.title, member: false, value: { kind: 'value', baseline: change.baseline, value: change.value }, basis: JSON.stringify([change.baseline, change.value]),
    default: proposed?.titles.get(key)?.title === change.value || answeredLookup(change) || (!change.baseline
      && (fromLookup(pathOf(change)) || atPair(change) || proposed?.numbers.get(key) === change.value)) });
  // A list or the label waits for an explicit choice while an identity row it owns needs an answer, and arrives once it is answered.
  const answered = (path: string) => !identity?.identities.some(row => row.needsAnswer && row.entries.some(entry => entry.path === path));
  changes.filter(change => change.scope === 'album').forEach(change => field(change));
  const album = (name: 'artists' | 'label' | 'expectedTracklist', value: ApplyValue, selected = true) =>
    add({ key: reviewFieldKey({ scope: 'album', slotId: null, field: name }), scope: 'album', slotId: null, field: name, title: source.album.title, member: false, value,
      basis: JSON.stringify(draft.album[name] ?? null), default: selected });
  if (reads && identity.album && identity.selection.lists.includes('album.artists')) {
    const current = artistEntries(identity.album.current), next = artistEntries(identity.album.next);
    album('artists', { kind: 'credits', current, next, idsOnly: sameCredits(current, next) }, answered('album.artists'));
  }
  if (reads && identity.album && identity.selection.label) {
    const current = firstLabel(identity.album.current), next = firstLabel(identity.album.next);
    album('label', { kind: 'credits', current, next, idsOnly: sameCredits(current, next) }, !identity.label?.needsAnswer);
  }
  const rows = draft.album.expectedTracklist ?? null;
  if (reads && rows && pairs && JSON.stringify(rows) !== JSON.stringify(identity.keptTracklist)) album('expectedTracklist', { kind: 'tracklist', keptRows: identity.keptTracklist?.length ?? null, keptNoFile: 0, rows: rows.length, noFile: 0 });
  changes.filter(change => change.scope === 'track').forEach(change => field(change));
  for (const track of draft.tracks) {
    const member = reads ? identity.members.find(value => value.slotId === track.slotId) : undefined;
    if (member) add({ key: memberKey(track.slotId), scope: 'track', slotId: track.slotId, field: 'artists', title: source.tracks.find(value => value.slotId === track.slotId)?.title ?? '',
      member: true, value: { kind: 'member', current: member.current, next: member.next, removed: member.current.filter(credit => credit.creditId !== null && member.removedCreditIds.includes(credit.creditId)),
        attribution: member.attribution, idsOnly: !member.credits }, basis: JSON.stringify(track.artists ?? null), default: answered(`tracks.${track.slotId}.artists`) });
  }

  const intended = (entry: ApplyItem & { default: boolean }) => { const choice = choices[entry.key]; return choice?.basis === entry.basis ? choice.checked : entry.default; };
  for (const entry of items) if (open.has(pathOf(entry))) entry.hold = 'conflict';
  const counted = (entry: ApplyItem & { default: boolean }) => intended(entry) && entry.hold === null;
  // A member's number after the selection as it stands: its counted draft value, else the captured one.
  const after = (slotId: string, name: 'discNumber' | 'trackNumber') => {
    const entry = items.find(candidate => candidate.slotId === slotId && candidate.field === name);
    return (entry && counted(entry) ? draft : source).tracks.find(value => value.slotId === slotId)![name] ?? null;
  };
  const members = () => new Map<string, Numbers>(source.tracks.map(({ slotId }) => [slotId, { slotId, discNumber: after(slotId, 'discNumber'), trackNumber: after(slotId, 'trackNumber') }]));
  // Each member's numbers after the selection, a pairing-filled number counted while intended.
  const numbers = members();
  const placedAt = (rowsAt: readonly { discNumber: number; trackNumber: number }[], pair: { slotId: string; discNumber: number; trackNumber: number }) =>
    rowsAt.some(row => row.discNumber === pair.discNumber && row.trackNumber === pair.trackNumber) && positionOf(numbers.get(pair.slotId)) === `${pair.discNumber}:${pair.trackNumber}`;
  const tracklist = items.find(entry => entry.field === 'expectedTracklist');
  if (tracklist && rows && pairs) {
    tracklist.offSlotIds = pairs.filter(pair => !placedAt(rows, pair)).map(pair => pair.slotId);
    if (tracklist.hold === null && tracklist.offSlotIds.length) tracklist.hold = 'placement';
    const kept = identity?.keptTracklist;
    tracklist.value = { kind: 'tracklist', keptRows: kept?.length ?? null, keptNoFile: kept ? expectedRowMembers(kept, source.tracks.map(track => ({ slotId: track.slotId,
      discNumber: track.discNumber ?? null, trackNumber: track.trackNumber }))).noFile : 0, rows: rows.length, noFile: expectedRowMembers(rows, [...numbers.values()]).noFile };
  }
  const withTracklist = Boolean(tracklist && counted(tracklist));
  // A pairing-filled number applies with the tracklist, or alone where the Album's kept tracklist places its member at its pair's row.
  // An unticked one is held by nothing, so it can be ticked again.
  for (const entry of items) {
    if (entry.hold !== null || !filled.has(pathOf(entry)) || !intended(entry)) continue;
    const pair = pairs?.find(value => value.slotId === entry.slotId), kept = identity?.keptTracklist;
    if (!withTracklist && !(pair && kept && placedAt(kept, pair))) entry.hold = 'tracklist';
  }
  // A cleaned title drops its position, so it applies only where its member's numbers keep it: selected, or already stored.
  for (const entry of items) {
    const needs = proposed?.titles.get(entry.key);
    if (needs && needs.title === (entry.value as { value?: unknown }).value && entry.hold === null && intended(entry) && needs.numbers.some(name => after(entry.slotId!, name) === null)) entry.hold = 'numbers';
  }
  for (const entry of items) entry.selected = counted(entry);

  const selected = items.filter(entry => entry.selected);
  const lists = new Set(selected.filter(entry => entry.field === 'artists').map(entry => entry.member ? `tracks.${entry.slotId}.artists` : 'album.artists'));
  const label = selected.some(entry => entry.field === 'label');
  const rowsOwned = identity?.identities.filter(row => row.entries.some(entry => lists.has(entry.path))) ?? [];
  const owned = new Set(rowsOwned.map(row => row.id)), shown = (value: { scope: 'artist' | 'label'; identity: string | null }) => value.scope === 'label' ? label : owned.has(value.identity!);
  const hiddenAlbum = source.album.visibility === 'hidden';
  const identities: ApplyIdentityLine[] = [...rowsOwned.map(row => ({ ...row, handle: row.id, scope: 'artist' as const, bound: row.bound })),
    ...(label && identity?.label ? [{ ...identity.label, handle: 'label', scope: 'label' as const, state: identity.label.state as 'bound' | 'unbound', bound: identity.label.bound ? [identity.label.bound] : [] }] : [])]
    .map(row => {
      const answer = row.state === 'unbound' ? row.decision ?? row.preselection : null;
      // A decided or preselected record listed at another revision changed since: its row needs an answer again.
      const candidate = answer && answer.action !== 'create-distinct' ? identity!.candidates.items.find(value => value.id === answer.candidateId && value.revision === answer.candidateRevision) : undefined;
      const records = row.state !== 'unbound' ? row.bound.map(record => ({ name: record.name, hidden: record.visibility === 'hidden' }))
        : candidate ? [{ name: candidate.label, hidden: candidate.visibility === 'hidden' }] : answer?.action === 'create-distinct' ? [{ name: row.name, hidden: hiddenAlbum }] : [];
      const outcome = row.state === 'bound' ? 'reuse' : row.state === 'conflicting' ? 'conflicting' : candidate ? 'reuse' : answer?.action === 'create-distinct' ? 'create' : 'undecided';
      const write = row.musicBrainzIdWrite;
      return { handle: row.handle, scope: row.scope, name: row.name, musicBrainzId: row.musicBrainzId, outcome, records, needsAnswer: row.needsAnswer,
        idWrite: write && { musicBrainzId: write.musicBrainzId, replaces: write.replaces, record: write.replaces ? records[0]?.name ?? null : null } };
    });
  // Positions as the Album page places them after the apply; a group already shared in the catalog blocks only once a selected
  // number moves a member into it. A selected number outside the server's bounds blocks too (stored ones are always within).
  const claimed: Record<string, string[]> = {}, outside: string[] = [], positions: ApplyPositionBlock[] = [];
  for (const value of members().values()) {
    if (!/^[1-9]\d{0,2}:[1-9]\d{0,3}$/.test(`${value.discNumber ?? 1}:${value.trackNumber ?? 1}`)) outside.push(value.slotId);
    const at = positionOf(value);
    if (at) (claimed[at] ??= []).push(value.slotId);
  }
  for (const slotIds of Object.values(claimed)) if (slotIds[1] && selected.some(entry => numeric(entry.field) && slotIds.includes(entry.slotId!))) positions.push({ reason: 'duplicate', slotIds });
  if (outside.length) positions.push({ reason: 'range', slotIds: outside });
  const blocking = { lookup: Boolean(waiting?.lookup), identities: identities.filter(line => line.needsAnswer).map(line => line.name), positions };

  // The note on Album Credits never copied to tracks, when the selected Artist entries change the Album's primary Artists.
  const albumArtists = selected.find(entry => entry.key === 'album::artists'), albumCredits = identity?.album;
  const primaries = (credits: CreditView[]) => JSON.stringify(credits.filter(credit => credit.role === 'primary').map(credit => [credit.subjectId, credit.name]));
  let albumNote: ReviewApplySelection['albumNote'] = null;
  if (albumArtists?.value.kind === 'credits' && albumCredits && primaries(albumArtists.value.current) !== primaries(albumArtists.value.next)) {
    const replaced = new Set(albumCredits.replacedPrimaryArtistIds);
    albumNote = { namingReplaced: draft.tracks.map(track => track.slotId).filter(slotId => {
      const member = identity!.members.find(value => value.slotId === slotId);
      if (!member) return albumCredits.membersNamingReplaced.includes(slotId);
      const credits = lists.has(`tracks.${slotId}.artists`) ? member.next : member.current;
      return credits.some(credit => credit.subjectType === 'artist' && credit.subjectId !== null && replaced.has(credit.subjectId));
    }) };
  }

  const plain = items.map(({ default: _default, ...entry }) => entry);
  const fields: ReviewField[] = selected.filter(entry => !entry.member).map(({ scope, slotId, field }) => ({ scope, slotId, field: field as ReviewField['field'] }));
  const memberCredits = selected.filter(entry => entry.member).map(entry => entry.slotId!);
  const selection: ReviewApplySelection = { fields, memberCredits, preselections: identity?.preselections.filter(shown) ?? [], musicBrainzIds: identity?.musicBrainzIds.filter(shown) ?? [],
    items: plain.filter(entry => entry.selected), identities, albumNote };
  const at = (read: { revision: number; valueRevision: number } | null) => read !== null && read.revision === item.revision && read.valueRevision === item.valueRevision;
  const current = !captured || (waiting !== null && at(summary) && at(identity));
  return { items: plain, selection, blocking, ready: fields.length + memberCredits.length > 0 && !waiting?.lookup && !waiting?.analysis && !blocking.identities.length
    && !positions.length && !edited && current };
}
